R=Path(__file__).resolve().parent
info=json.loads((R/'evidence/resumen_verificacion.json').read_text())
with (R/'evidence/resultados_pruebas.csv').open(encoding='utf8') as f:cases=list(csv.DictReader(f))
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='SigmaTitle',parent=styles['Title'],fontSize=23,leading=29,textColor=colors.HexColor('#133B59'),spaceAfter=12));styles.add(ParagraphStyle(name='SigmaH',parent=styles['Heading2'],fontSize=13,leading=17,textColor=colors.HexColor('#1A638A'),spaceBefore=14,spaceAfter=6));styles.add(ParagraphStyle(name='SigmaBody',parent=styles['BodyText'],fontSize=9.3,leading=14,spaceAfter=7));styles.add(ParagraphStyle(name='SigmaSmall',parent=styles['BodyText'],fontSize=7.5,leading=10))
def P(t,style='SigmaBody'):return Paragraph(t,styles[style])
def build_pdf(path,title,sections):
 doc=SimpleDocTemplate(str(path),pagesize=(21*cm,29.7*cm),leftMargin=1.9*cm,rightMargin=1.9*cm,topMargin=1.7*cm,bottomMargin=1.7*cm)
 story=[P(title,'SigmaTitle'),P('SIGMA Retail AI | Tópicos Especiales para la Gestión de Datos | Parcial 01'),P('Equipo XX (reemplazar por número y participantes). Versión académica 1.0. Datos comerciales sintéticos.'),Spacer(1,13)]
 for heading,body in sections:
  story.append(P(heading,'SigmaH'))
  if isinstance(body,list):
   for t in body:story.append(P('• '+t))
  else:story.append(P(body))
 def foot(c,d):
  c.setFont('Helvetica',8);c.setFillColor(colors.grey);c.drawRightString(19.1*cm,1.2*cm,str(d.page))
 doc.build(story,onFirstPage=foot,onLaterPages=foot)
report=[
('1. Planteamiento y alcance','Prototipo para gerentes de una cadena comercial ficticia: recibir preguntas de ventas, traducirlas a consultas SQL controladas y mostrar resultados con procedencia. Incluye 7 preguntas obligatorias y 3 preguntas adicionales. No responde preguntas sin evidencia ni ejecuta SQL destructivo.'),
('2. Justificación arquitectónica','Se adopta la separación entre (a) fuente operacional sintética y ETL reproducible; (b) Data Mart dimensional SQLite en lectura; (c) objetos del agente persistidos por ZODB; y (d) interfaz Streamlit. Esta separación respeta la arquitectura DW/BI presentada en P04 y el propósito de la BDOO señalado por P06.'),
('3. Grano y dimensiones','Grano exacto: cada fila en fact_ventas representa una línea de producto incluida en un ticket de venta, asociada a una fecha, cliente histórico, sucursal, canal y promoción. Dimensiones: tiempo (fecha/mes/trimestre/año); producto (producto/categoría); cliente (cliente/segmento); sucursal; canal; promoción. Todas poseen claves sustitutas; FactVentas tiene clave primaria compuesta (ticket_id,linea_nro) para prevenir duplicación de líneas.'),
('4. Modelo dimensional y datos','Esquema en estrella: fact_ventas se conecta directamente a las 6 dimensiones, sin subdimensiones normalizadas. Se carga un calendario 2026, 12 productos, 60 clientes naturales, 4 sucursales, 3 canales y 3 promociones. El conjunto generado contiene %s tickets y %s líneas, mediante semilla fija 42026. Las fechas y nombres comerciales son ficticios.'%(info['tickets'],info['lineas'])),
('5. Métricas y naturaleza de aditividad',['Ingreso bruto, descuento, devolución, costo, ingreso neto, margen bruto y unidades: aditivos a nivel de línea, con cuidado de no agregar medidas por dimensiones multiplicadas por JOINs.','Ticket promedio y margen porcentual: no aditivos, se recalculan tras agrupar los numeradores y denominadores. Ticket promedio = SUM(ingreso neto)/COUNT(DISTINCT ticket_id).','No se almacena un hecho semiaditivo en este modelo de ventas; un saldo de inventario o clientes activos al cierre sería semiaditivo respecto del tiempo y requeriría una tabla de instantáneas diferente.']),
('6. Cálculos de negocio','Ingreso neto = ingreso bruto − descuento − devolución. Margen bruto = ingreso neto − costo. Importes almacenados en céntimos enteros para evitar desajustes de precisión. El total generado de ingreso neto es %.2f y el margen bruto %.2f (unidades monetarias de demostración). Los reembolsos del dataset son completos y su costo se fija en cero como simplificación documentada.'%(info['ingreso_neto'],info['margen_bruto'])),
('7. Calidad, desconocidos, SCD y conciliación','Los registros cargados usan claves foráneas válidas y campos esenciales no nulos; el esquema impide líneas duplicadas, cantidad negativa y cálculos incoherentes. Para integración futura: registrar claves desconocidas con miembro sustituto “Desconocido”, conservar cuarentena de registros que no puedan mapearse y emitir reporte de rechazos; esta política futura no está implementada en el generador sintético. Cliente usa SCD2 con vigencias sin solapamiento: cuando cambia de segmento se inserta nueva fila con distinta clave sustituta y los hechos conservan la anterior. Los controles de fuente validan conteo, totales, referencias y vigencias.'),
('8. OLTP frente a analítica','Las fuentes OLTP registran eventos transaccionales, mientras que el Data Mart mantiene medidas históricas consultables en agregado; en esta demostración el generador simula entradas de operaciones y las transforma a la estructura dimensional. No se conecta a un sistema de producción.'),
('9. Base de datos orientada a objetos','Las clases son AgenteAnalitico, Usuario, Sesion, Pregunta, Intencion, ConsultaAnalitica, ResultadoConsulta, RespuestaAgente, FuenteDato y ReglaValidacion. Sesion compone su historial de interacciones; objetos contienen estado y algunos métodos (ej. validar y registrar). La persistencia se implementa con ZODB FileStorage, no como duplicación de dimensiones. Hay un límite: la instalación y ejecución de ZODB no se pudieron probar en este entorno sin conectividad de paquetes.'),
('10. Patrón de interpretación y ejecución','Se normaliza el texto de la pregunta, se detectan palabras clave, se elige una de diez plantillas del catálogo, se comprueban los parámetros autorizados, se abre SQLite en modo read-only y se ejecuta el SQL. El resultado se transforma en respuesta gerencial con métrica, dimensión, cálculo, fuente y periodo. La consulta SQL y sus parámetros quedan disponibles en el panel de auditoría. El intérprete local es determinista, no es un modelo de lenguaje generativo.'),
('11. Manejo de límites','Ambigüedad “mejor canal”: rechazo y aclaración del criterio. Periodo omitido: la pregunta sobre ingresos por mes devuelve 2026, único año del dataset. Fuera de dominio, dimensión inexistente y operación destructiva: rechazo; sin registros: aviso explícito, nunca valor cero. Preguntas no reconocidas: catálogo de consultas disponible.'),
('12. Pruebas y resultados','Matriz de %d casos, de los cuales %d fueron aprobados en la verificación local del núcleo SQL/agente. Incluye las 10 familias, casos negativos, consultas ambiguas, sin periodo, sin resultados y no autorizadas. Integridad y conciliación: %s. La validación de la interfaz web y la persistencia real de ZODB siguen pendientes de ejecutar en un entorno con dependencias instaladas.'%(info['casos'],info['aprobados'],', '.join(x[0]+': '+('OK' if x[1] else 'ERROR') for x in info['controles']))),
('13. Límites y mejoras','Alcance de lenguaje natural restringido; falta integración con ERP o fuentes externas; el catálogo no generaliza a consultas arbitrarias; no existe interfaz LLM actualmente; periodo disponible definido por calendario y no por fecha de última venta; se requiere una prueba de persistencia extremo a extremo con ZODB/Streamlit. Mejoras: integrar LLM solo para extracción estructurada de intenciones, controles de validación semántica, seguimiento de calidad ETL y automatización CI.'),
('14. Procedimiento para reproducir','Instalar Python 3.11+, ejecutar pip install -r requirements.txt, python -m sigma.generate, python -m pytest -q y streamlit run app.py. Verificar sql/02_controles.sql y evidence/resumen_verificacion.json. La bitácora de IA debe actualizarse con el registro real de acciones antes de entregar. No incluir secretos.'),
('15. Vinculación con clases P04–P06','P04: distinción OLTP/DW, ETL y arquitectura de BI; P05: grano, esquema estrella, claves sustitutas y SCD2; P06: identidad de objetos, métodos, encapsulamiento, composición e historia persistente. Los artefactos aportan una aplicación concreta de esos contenidos. Fuentes primarias: material de clases del profesor Armen Djenanian y enunciado del Parcial 01.')]
build_pdf(R/'EquipoXX_Informe_Parcial01.pdf','Informe técnico | SIGMA Retail AI',report)
bit=[('Registro del uso de IA y decisiones', 'Herramienta: asistente IA para apoyo en diseño y generación de código. Prompt del usuario: “Mi decisión sobre SIGMA Retail AI es: Apruebo la propuesta. Integración LLM: opcional. Desarrolla el proyecto según la decisión y conserva los requisitos del enunciado.” Resultado: propuesta implementada con DDL, datos sintéticos, SQL, clases, interfaz y pruebas. Componentes: arquitectura completa. Validación: pruebas automatizadas SQL/agente, verificaciones de integridad y conciliación. Decisión: aceptar con ajustes y advertencias; no declarar comprobados Streamlit ni ZODB.'),('Correcciones documentadas','Se detectó que el intérprete inicial no reconocía la forma “redujo”; se modificó el conjunto de variantes léxicas y se repitió la prueba. Decisión: modificar. Resultado final del núcleo: %d/%d casos de matriz aprobados.'%(info['aprobados'],info['casos'])),('Dependencias y prueba pendiente','Se intentó instalar ZODB y Streamlit en el entorno de elaboración y se detectó fallo de conectividad al repositorio de paquetes. Por ello no se pudo certificar la ejecución de la interfaz ni la persistencia ZODB. Decisión: conservar código fuente y añadir instrucciones de instalación/verificación en entorno con Internet.'),('Declaración de uso responsable','No se han inventado resultados de pruebas visuales de Streamlit ni evidencia de objetos efectivamente escritos con ZODB. Cualquier validación posterior deberá anexar capturas, fechas y resultados reales. La herramienta de IA es un apoyo; el equipo asume responsabilidad de comprender, revisar y defender cada componente.')]
build_pdf(R/'EquipoXX_BitacoraIA.pdf','Bitácora de uso de IA',bit)
# PDF complementario BDOO
bdoo=[('Catálogo de objetos',', '.join(['AgenteAnalitico','Usuario','Sesion','Pregunta','Intencion','ConsultaAnalitica','ResultadoConsulta','RespuestaAgente','FuenteDato','ReglaValidacion'])+'. Cada pregunta se relaciona con intención, consulta, resultado y respuesta.'),('Relaciones y comportamiento','Un Usuario crea varias Sesiones; cada Sesion compone su lista de interacciones; una interacción compone Pregunta, ConsultaAnalitica, ResultadoConsulta y RespuestaAgente; una RespuestaAgente refiere FuenteDato. ConsultaAnalitica.validar controla que solo se consulten SELECT/CTE; Sesion.registrar actualiza el historial; AgenteAnalitico.responder delega ejecución.'),('Implementación de persistencia','El adaptador ZODB de sigma/store.py escribe un PersistentMapping que indexa objetos Sesion por ID. Las sesiones y su contenido se serializan como grafos de objetos Python. El modelo incluye identificadores UUID propios para referencia; no son equivalentes al identificador interno de ZODB (OID).'),('Estado de validación','La clase, el adaptador y su configuración están implementados, pero no se certifica la ejecución del almacenamiento ZODB al no disponer de dependencias instalables en este entorno. Se debe probar una sesión persistida, cerrar/reabrir el proceso y recuperar la interacción antes de la entrega definitiva.')]
build_pdf(R/'EquipoXX_EvidenciaBDOO.pdf','Diseño OO y evidencia de persistencia',bdoo)
# presentation
prs=Presentation();prs.slide_width=Inches(13.333);prs.slide_height=Inches(7.5)
slide_data=[('SIGMA Retail AI','Parcial 01 · Agente analítico con Data Mart y BDOO\nEquipo XX · datos de demostración sintéticos'),('Problema y objetivo','Gerencia necesita consultar ventas sin SQL.\nRespuesta verificable con evidencia; fuera de alcance se rechaza.'),('Arquitectura','Generador ETL simulado → SQLite/Data Mart\nPregunta → intérprete/catálogo → SQL solo lectura\nObjetos Sesion/Pregunta/Resultado → ZODB → trazabilidad\nStreamlit → respuestas y consulta auditable'),('Modelo dimensional','Grano = una línea de un ticket\nFactVentas + Tiempo, Producto, Cliente, Sucursal, Canal y Promoción\nClaves sustitutas y SCD2 en segmento del cliente'),('Métricas y calidad','Ingreso neto = bruto − descuento − devolución\nMargen bruto = neto − costo\nTicket = SUM(neto)/COUNT(DISTINCT ticket_id)\nConciliación fuente y claves foráneas: OK'),('Modelo orientado a objetos','10 clases del enunciado\nSesión compone historial Pregunta → Consulta → Resultado → Respuesta\nMétodos de validación y registro\nPersistencia propuesta: ZODB'),('Flujo de la demostración','1. Preguntar ingresos netos por mes\n2. Mostrar respuesta y filas SQL\n3. Mostrar parámetros y fuente\n4. Preguntar “mejor canal” para demostrar ambigüedad\n5. Comprobar historial de sesión'),('Pruebas','%d escenarios de matriz; %d aprobados en núcleo local\nIncluye 7 consultas requeridas + 3 adicionales\nSin datos ≠ cero; SQL destructivo denegado\nVerificación ZODB/Streamlit: pendiente'% (info['casos'],info['aprobados'])),('Decisiones y límites','Interprete local, LLM opcional no conectado\nDatos sintéticos 2026\nCatálogo cerrado de intenciones, no SQL arbitrario\nFuturo: ampliar parser e integrar sistemas reales'),('Conclusión y preguntas','Los indicadores proceden únicamente del Data Mart.\nLa BDOO representa comportamiento y trazabilidad.\nVerificación de la ejecución final: completar en entorno del equipo.')]
